// План specs/dashboard.md 2.2, 2.3 (кейсы DB-05, DB-06). Десктоп 1440, admin, компания «test».
// Меняет только localStorage своего окна (ключи techory:dashboard-tip:*), очищает их в начале и в конце (@prod-safe).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { greetingCard } from './dashboard-helpers';
import {
  TIPS, dismissedTipKeys, expectNoInvoicesDueInCard, hideTipButton, openDashboardFresh, removeTipKeys,
  tipLink, waitForTip, waitTipWindowPassed,
} from './dashboard-tips-helpers';

test.use({ storageState: ADMIN_STATE });

const KNOWN_TIPS = Object.values(TIPS);

test.describe('Дашборд, десктоп: скрытие советов в карточке приветствия (#444b9ee7)', () => {
  test.afterEach(async ({ page }) => { await removeTipKeys(page); });

  test('Desktop dashboard EN: first tip "Take card payments", X shows "Finish your company profile", hidden tip does not return after reload #444b9ee7 @desktop @prod-safe', async ({ page }) => {
    await openDashboardFresh(page, 'en');
    await waitForTip(page, 'en');

    await expect(tipLink(page, 'en')).toHaveText(TIPS.stripe.text);
    await expect(tipLink(page, 'en')).toHaveAttribute('href', TIPS.stripe.href);

    await hideTipButton(page, 'en').click();
    await expect(tipLink(page, 'en')).toHaveText(TIPS.profile.text);
    await expect(tipLink(page, 'en')).toHaveAttribute('href', TIPS.profile.href);
    await expect.poll(() => dismissedTipKeys(page), { message: 'скрытый совет записан в localStorage' }).toHaveLength(1);

    await page.reload();
    await expect(greetingCard(page)).toBeVisible();
    await waitForTip(page, 'en');
    await expect(tipLink(page, 'en')).toHaveText(TIPS.profile.text);
    await expect(greetingCard(page)).not.toContainText(TIPS.stripe.text);
  });

  test('Desktop dashboard EN: after hiding all tips no tip is shown, card shows "On your schedule", also after reload #444b9ee7 @desktop @prod-safe', async ({ page }) => {
    await openDashboardFresh(page, 'en');
    await waitForTip(page, 'en');

    const seen: string[] = [];
    for (let i = 0; i < KNOWN_TIPS.length + 2 && (await hideTipButton(page, 'en').count()) > 0; i++) {
      const text = (await tipLink(page, 'en').innerText()).trim();
      const tip = KNOWN_TIPS.find((t) => t.text === text);
      expect(tip, `совет «${text}» — из известного списка`).toBeTruthy();
      await expect(tipLink(page, 'en')).toHaveAttribute('href', tip!.href);
      expect(seen, `совет «${text}» не повторяется`).not.toContain(text);
      seen.push(text);

      await hideTipButton(page, 'en').click();
      // Следующий совет или конец списка.
      await expect.poll(async () =>
        (await hideTipButton(page, 'en').count()) === 0 || (await tipLink(page, 'en').innerText()).trim() !== text,
      ).toBe(true);
    }

    expect(seen.length, 'показано и скрыто больше одного совета').toBeGreaterThan(1);
    await expect(hideTipButton(page, 'en')).toHaveCount(0);
    await expect(greetingCard(page)).toContainText('On your schedule');
    await expectNoInvoicesDueInCard(page);
    expect(await dismissedTipKeys(page)).toHaveLength(seen.length);

    await page.reload();
    await expect(greetingCard(page)).toBeVisible();
    await waitTipWindowPassed(page);
    await expect(hideTipButton(page, 'en')).toHaveCount(0);
    await expect(greetingCard(page)).toContainText('On your schedule');
  });
});
